// Plantilla del correo con los colores de la licorería (blanco y lila)
const e = (v) => String(v ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
const plantilla = (titulo, contenido) => `
<div style="font-family:Segoe UI,Arial,sans-serif;background:#f7f4ff;padding:24px;color:#241a38">
  <div style="max-width:620px;margin:0 auto;background:#fff;border:1px solid #ebe7f4;border-radius:14px;overflow:hidden">
    <div style="background:linear-gradient(135deg,#8b5cf6,#6a2fd0);color:#fff;padding:18px 24px;font-size:18px;font-weight:700">Licorería · ${e(titulo)}</div>
    <div style="padding:20px 24px;font-size:14px;line-height:1.5">${contenido}</div>
    <div style="padding:12px 24px;background:#faf9fd;color:#6c6880;font-size:12px">Correo automático de n8n. No responder.</div>
  </div>
</div>`;
const tabla = (cabeceras, filas) => `<table style="border-collapse:collapse;width:100%;font-size:13px"><tr>${cabeceras.map((c, i) =>
  `<th style="text-align:${i ? 'right' : 'left'};padding:6px 8px;border-bottom:2px solid #ddd2fe;color:#6a2fd0">${e(c)}</th>`).join('')}</tr>${filas.map((f) =>
  `<tr>${f.map((v, i) => `<td style="text-align:${i ? 'right' : 'left'};padding:6px 8px;border-bottom:1px solid #ebe7f4">${e(v)}</td>`).join('')}</tr>`).join('')}</table>`;

const aviso = $('Aviso de stock bajo').first().json.body ?? {};
const r = $input.first().json;   // respuesta del agente, o { error } si no respondió
const producto = `${aviso.nombre ?? aviso.productoCodigo} (${aviso.productoCodigo})`;
const datos = tabla(['Producto', 'Quedan', 'Mínimo'], [[producto, aviso.cantidad, aviso.minimo]]);

let asunto, contenido;
if (!r.error && r.ordenCreada) {
  const lineas = (r.lineas ?? []).map((l) => [l.productoCodigo ?? l.producto ?? '', l.cantidad ?? '', l.precioUnitario ?? '']);
  asunto = `Orden de compra ${r.numero} creada por stock bajo de ${aviso.nombre ?? aviso.productoCodigo}`;
  contenido = `<p>El agente de reabastecimiento creó la orden de compra <b>${e(r.numero)}</b>.</p>${datos}
    <h3 style="color:#6a2fd0;margin:20px 0 8px">Líneas de la orden</h3>${tabla(['Producto', 'Cantidad', 'Precio unit. (Bs)'], lineas)}`;
} else {
  const motivo = r.error
    ? 'El agente de reabastecimiento (ms-ia) no respondió, así que no se creó una orden automática.'
    : (r.motivo ?? 'El agente decidió no crear una orden de compra.');
  asunto = `Stock bajo: ${aviso.nombre ?? aviso.productoCodigo} (quedan ${aviso.cantidad})`;
  contenido = `<p>${e(motivo)} Revise el producto y registre la orden de compra si hace falta.</p>${datos}`;
}
return [{ json: { asunto, cuerpo: plantilla('Stock bajo', contenido), ordenCreada: !r.error && !!r.ordenCreada } }];
